/usr/bin/bash -lc "python - <<'PY'
import urllib.request, tarfile, io, re
url='https://arxiv.org/src/1903.05032v4'
try:
    data=urllib.request.urlopen(url, timeout=25).read()
    print('Downloaded bytes:', len(data))
    with tarfile.open(fileobj=io.BytesIO(data), mode='r:*') as archive:
        for entry in archive.getmembers():
            if entry.name.endswith('.tex'):
                source=archive.extractfile(entry).read().decode(errors='replace')
                lines=source.splitlines()
                marks=[i for i,line in enumerate(lines) if re.search(r'overline\\{W\\}|L_\\{\\\\alpha|pi_\\{?\\\\alpha|Ind.*Res.*W',line)]
                print('Source:', entry.name)
                shown=set()
                for i in marks:
                    for j in range(max(0,i-8), min(len(lines),i+12)):
                        if j not in shown:
                            print(f'{j+1}: {lines[j]}')
                            shown.add(j)
except Exception as exc:
    print(type(exc).__name__, str(exc))
PY"
